    /// THIN-HARNESS-REDESIGN R1 (§4.4): 每次调用即闭环——每个派发新建
    /// 激活（fresh activation_id / contract_revision 0 / 新预算与新候选
    /// 计数），auto_close 后不再复用；黑板分区按 P2-3 用户裁决全量覆盖
    /// （response / entries / ledger 替换，分区代表最近一次派发）。
    #[tokio::test]
    async fn subagent_dispatch_creates_fresh_activation_per_call() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };

        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-1")]),
            ScriptedResponse::text("[DOC] a.md\n第一批"),
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-2")]),
            ScriptedResponse::text("[DOC] b.md\n第二批"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway));
        // R1 (§4.6): 生产默认阈值 50；这些场景固定 7 保持原触发语义。
        let mut orientation =
            crate::orientation::OrientationSessionState::new_with_threshold("sess-abcdef123456", 7);
        controller
            .run_turn(
                &host,
                "查找项目文档",
                "RUN-ID",
                MANIFEST,
                0,
                None,
                Some(&mut orientation),
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        let assessments: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::InformationSufficiencyAssessment)
            .collect();
        assert_eq!(assessments.len(), 2);
        let p0 = &assessments[0].payload;
        let p1 = &assessments[1].payload;
        // session8 = "sess-abc" — the first 8 chars of the session id.
        assert_eq!(
            p0.get("activation_id").and_then(|v| v.as_str()),
            Some("retrieval-internal_retrieval-sess-abc-00")
        );
        assert_eq!(
            p1.get("activation_id").and_then(|v| v.as_str()),
            Some("retrieval-internal_retrieval-sess-abc-01"),
            "auto-close 后新派发新建激活"
        );
        assert_eq!(
            p0.get("contract_id").and_then(|v| v.as_str()),
            Some("retrieval-contract-internal_retrieval")
        );
        // auto-close：两次派发均 revision 0（无 continue 递增）。
        assert_eq!(p0.get("contract_revision"), Some(&serde_json::json!(0)));
        assert_eq!(p1.get("contract_revision"), Some(&serde_json::json!(0)));
        // 每条派发一条 auto_close close record（每激活一条，verifier
        // 同 activation 单 close 规则满足）。
        let closes: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::RetrievalCloseRecord)
            .collect();
        assert_eq!(closes.len(), 2, "{:?}", event_types(&dir));
        assert!(closes.iter().all(|c| {
            c.payload.get("terminal_reason").and_then(|v| v.as_str()) == Some("auto_close")
        }));
        // 无 disposition 事件（close/continue 往返已退役）。
        assert_eq!(
            events
                .iter()
                .filter(|e| e.event_type == EventType::RetrievalParentDisposition)
                .count(),
            0
        );
        // 黑板分区覆盖语义（P2-3 用户裁决选 a）——最近一次派发替换。
        let r = controller.blackboard().read();
        assert_eq!(r.internal_ret.project_docs, vec!["b.md"]);

        let _ = std::fs::remove_dir_all(&dir);
    }

    fn disposition_call(
        role: &str,
        decision: &str,
        delta: Option<&str>,
        call_id: &str,
    ) -> ToolCall {
        let mut arguments = serde_json::json!({
            "role": role,
            "decision": decision,
        });
        if let Some(d) = delta {
            arguments["requirement_delta"] = serde_json::Value::String(d.to_string());
        }
        ToolCall {
            name: "retrieval_disposition".to_string(),
            arguments,
            call_id: call_id.to_string(),
        }
    }

    /// THIN-HARNESS-REDESIGN R1 (§4.4): 派发成功即 auto_close close
    /// record（assessment + result_digest 绑定，terminal_reason
    /// auto_close）；对已关闭激活的迟到 retrieval_disposition 调用一律
    /// 机械拒绝（no_pending_assessment，零 disposition 事件、零二次
    /// close）。
    #[tokio::test]
    async fn dispatch_auto_closes_and_late_disposition_refused() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };

        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-1")]),
            ScriptedResponse::text("[DOC] a.md\n检索完成"),
            ScriptedResponse::tool_calls(vec![disposition_call(
                "internal_retrieval",
                "close",
                None,
                "call-d1",
            )]),
            ScriptedResponse::tool_calls(vec![disposition_call(
                "internal_retrieval",
                "close",
                None,
                "call-d2",
            )]),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway));
        let mut orientation =
            crate::orientation::OrientationSessionState::new_with_threshold("sess-abcdef123456", 7);
        controller
            .run_turn(
                &host,
                "查找项目文档",
                "RUN-CLOSE",
                MANIFEST,
                0,
                None,
                Some(&mut orientation),
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        // 无 disposition 事件（close/continue 往返已退役）。
        assert_eq!(
            events
                .iter()
                .filter(|e| e.event_type == EventType::RetrievalParentDisposition)
                .count(),
            0
        );
        // 一条 auto_close close record（assessment + digest 绑定）。
        let closes: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::RetrievalCloseRecord)
            .collect();
        assert_eq!(closes.len(), 1);
        let c = &closes[0].payload;
        assert_eq!(
            c.get("terminal_reason").and_then(|v| v.as_str()),
            Some("auto_close")
        );
        assert_eq!(
            c.get("validated_disposition_id"),
            Some(&serde_json::Value::Null),
            "auto_close 不引用 disposition"
        );
        assert!(c.get("assessment_id").is_some());
        let digest = c.get("result_digest").and_then(|v| v.as_str()).unwrap();
        assert_eq!(digest.len(), 64, "64-hex sha256 for auto_close");
        assert_eq!(c.get("contract_revision"), Some(&serde_json::json!(0)));
        // 迟到的两次 disposition 调用被拒（no_pending_assessment）。
        assert_eq!(
            events
                .iter()
                .filter(|e| {
                    e.event_type == EventType::ToolCompleted
                        && e.payload.get("error").and_then(|v| v.as_str())
                            == Some("no_pending_assessment")
                })
                .count(),
            2
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// THIN-HARNESS-REDESIGN R1 (§4.4): auto-close 后再次派发 = 新激活
    /// （fresh activation_id、revision 0）；夹在中间的 retrieval_disposition
    /// 调用被机械拒绝（no_pending_assessment），不产生 disposition 事件、
    /// 不干扰两次 auto_close。
    #[tokio::test]
    async fn second_dispatch_after_auto_close_starts_fresh() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };

        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-1")]),
            ScriptedResponse::text("[DOC] a.md\n检索完成"),
            ScriptedResponse::tool_calls(vec![disposition_call(
                "internal_retrieval",
                "close",
                None,
                "call-d1",
            )]),
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-2")]),
            ScriptedResponse::text("[DOC] b.md\n检索完成"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway));
        controller
            .run_turn(
                &host,
                "查找项目文档",
                "RUN-REPLAY",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        // 零 disposition 事件；一次 no_pending_assessment 拒绝。
        assert_eq!(
            events
                .iter()
                .filter(|e| e.event_type == EventType::RetrievalParentDisposition)
                .count(),
            0
        );
        assert_eq!(
            events
                .iter()
                .filter(|e| {
                    e.event_type == EventType::ToolCompleted
                        && e.payload.get("error").and_then(|v| v.as_str())
                            == Some("no_pending_assessment")
                })
                .count(),
            1
        );
        // 两次派发 = 两个新激活 + 两条 auto_close close record。
        let assessments: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::InformationSufficiencyAssessment)
            .collect();
        assert_eq!(assessments.len(), 2);
        assert_eq!(
            assessments[0]
                .payload
                .get("activation_id")
                .and_then(|v| v.as_str()),
            Some("retrieval-internal_retrieval-RUN-REPL-00"),
            "无 orientation 时激活身份取 run_id 前 8 字符"
        );
        assert_eq!(
            assessments[1]
                .payload
                .get("activation_id")
                .and_then(|v| v.as_str()),
            Some("retrieval-internal_retrieval-RUN-REPL-01")
        );
        assert_eq!(
            assessments[0].payload.get("contract_revision"),
            Some(&serde_json::json!(0))
        );
        assert_eq!(
            assessments[1].payload.get("contract_revision"),
            Some(&serde_json::json!(0))
        );
        assert_eq!(
            events
                .iter()
                .filter(|e| e.event_type == EventType::RetrievalCloseRecord)
                .count(),
            2
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// THIN-HARNESS-REDESIGN R1 (§4.1): 主代理工具面收敛为硬保留 8 工具
    /// （framework_fallback 检索模式下）——删除项（list_dir/run_tests/
    /// search_tool/project_doc_index/pdf_read/plan_write/
    /// retrieval_disposition/retrieve_project_docs）与边界三项
    /// （todo_write/update_goal/compaction_whitelist_add）一律不在首轮
    /// 声明面。
    struct R1SurfaceRegistry;
    impl ToolRegistry for R1SurfaceRegistry {
        fn get(&self, name: &str) -> Option<ToolDef> {
            Self::all().into_iter().find(|t| t.name == name)
        }
        fn list(&self) -> Vec<ToolDef> {
            Self::all()
        }
    }
    impl R1SurfaceRegistry {
        fn all() -> Vec<ToolDef> {
            [
                "run_terminal_cmd",
                "read_file",
                "grep",
                "search_replace",
                "web_search",
                "web_fetch",
            ]
            .iter()
            .map(|n| ToolDef {
                name: n.to_string(),
                description: format!("tool {n}"),
                parameters: serde_json::json!({}),
            })
            .collect()
        }
    }
    struct R1SurfaceHost {
        journal: JournalRecorder,
    }
    #[async_trait]
    impl LoopHost for R1SurfaceHost {
        fn journal(&self) -> &JournalRecorder {
            &self.journal
        }
        fn tools_registry(&self) -> &dyn ToolRegistry {
            &R1SurfaceRegistry
        }
        fn tool_policy(&self) -> crate::host::ToolPolicy {
            // Interactive：run_terminal_cmd 探针完整（Benchmark 会剔除）。
            crate::host::ToolPolicy::Interactive
        }
        fn terminal_available(&self) -> bool {
            true
        }
        fn session_cwd(&self) -> std::path::PathBuf {
            self.journal.journal_dir().to_path_buf()
        }
        async fn request_permission(
            &self,
            _risk: RiskClass,
            _tool: &str,
            _args: &serde_json::Value,
        ) -> Result<PermitDecision, PermitError> {
            Ok(PermitDecision::AllowOnce)
        }
        async fn call_tool(
            &self,
            _name: &str,
            _args: serde_json::Value,
            _call_id: &str,
        ) -> Result<ToolResult, ToolError> {
            Ok(ok_result())
        }
    }

    #[tokio::test]
    async fn r1_main_surface_is_eight_tools() {
        let dir = test_dir();
        let host = R1SurfaceHost {
            journal: JournalRecorder::new(dir.clone()),
        };

        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        // framework_fallback：web 族在面内（与生产 CLI 跑分一致）。
        // framework_fallback：web 族在面内（与生产 CLI 跑分一致）；
        // console_default 启用 submit（生产路径同款）。
        let controller = with_retrieval_enabled(
            AgentLoopController::with_gateway(gateway).with_console_default_enabled(true),
        );
        controller
            .run_turn(&host, "完成任务", "RUN-SURF", MANIFEST, 0, None, None, None)
            .await
            .unwrap();

        let events = events(&dir);
        let initial = events
            .iter()
            .find(|e| {
                e.event_type == EventType::RequestHeaderChange
                    && e.payload.get("reason").and_then(|v| v.as_str()) == Some("initial")
            })
            .expect("initial request header");
        let tools: Vec<String> = initial.payload["tools"]
            .as_array()
            .expect("tools list")
            .iter()
            .map(|v| v.as_str().unwrap().to_string())
            .collect();
        // 硬保留 8 工具（framework_fallback：web 族可见；browser_read 不
        // 在面内）。删除项与边界项一律不出现。
        let expected = [
            "run_terminal_cmd",
            "read_file",
            "grep",
            "search_replace",
            "web_search",
            "web_fetch",
            "blackboard_read",
            "submit",
        ];
        for tool in &expected {
            assert!(
                tools.iter().any(|t| t == tool),
                "retained tool '{tool}' must be declared: {tools:?}"
            );
        }
        for banned in [
            "list_dir",
            "run_tests",
            "search_tool",
            "project_doc_index",
            "pdf_read",
            "plan_write",
            "retrieval_disposition",
            "retrieve_project_docs",
            "todo_write",
            "update_goal",
            "compaction_whitelist_add",
            "browser_read",
        ] {
            assert!(
                !tools.iter().any(|t| t == banned),
                "banned tool '{banned}' must NOT be declared: {tools:?}"
            );
        }

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// THIN-HARNESS-REDESIGN R1 (§4.4): auto-close 后连续两次检索派发
    /// 都成功——第二次不再被"awaiting disposition"拒（该状态已被每次调用
    /// 即闭环取代），产生两条 assessment 与两条 auto_close close record。
    #[tokio::test]
    async fn consecutive_dispatches_both_auto_close() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };

        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-1")]),
            ScriptedResponse::text("[DOC] a.md\n检索完成"),
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-2")]),
            ScriptedResponse::text("[DOC] b.md\n检索完成"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway));
        controller
            .run_turn(
                &host,
                "查找项目文档",
                "RUN-AWAIT",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        assert_eq!(
            events
                .iter()
                .filter(|e| e.event_type == EventType::InformationSufficiencyAssessment)
                .count(),
            2,
            "both dispatches formed results: {:?}",
            event_types(&dir)
        );
        assert_eq!(
            events
                .iter()
                .filter(|e| e.event_type == EventType::RetrievalCloseRecord)
                .count(),
            2,
            "both dispatches auto-closed: {:?}",
            event_types(&dir)
        );
        // 无 awaiting-disposition 拒绝（该拒绝路径已不可达）。
        assert!(
            !events.iter().any(|e| {
                e.event_type == EventType::ToolCompleted
                    && e.payload.get("error").and_then(|v| v.as_str())
                        == Some("activation_awaiting_disposition")
            }),
            "awaiting-disposition refusal must not fire under auto-close"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// M4: a user cancel closes every pending activation with a terminal
    /// close record BEFORE the run_cancelled terminal event.
    #[tokio::test]
    async fn user_cancel_closes_pending_activations_before_run_cancelled() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };

        // Slow-chunked subagent response — the cancel lands inside the
        // subagent stream (→ subagent_cancelled close), then propagates to
        // the run level (→ run_cancelled). The subagent_cancelled close
        // covers the activation; the user-cancel pass skips it (idempotent).
        let gateway: Arc<dyn ModelGateway> = Arc::new(
            FakeProvider::new(vec![
                ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-1")]),
                ScriptedResponse::text("[DOC] a.md\n检索完成"),
            ])
            .with_chunk_delay(std::time::Duration::from_millis(60)),
        );
        let controller = Arc::new(with_retrieval_enabled(AgentLoopController::with_gateway(
            gateway,
        )));
        let token = tokio_util::sync::CancellationToken::new();

        let c = controller.clone();
        let t = token.clone();
        let run = tokio::task::spawn(async move {
            c.run_turn_with_cancel(
                &host,
                "查找项目文档",
                "RUN-UC",
                MANIFEST,
                0,
                None,
                Some(&t),
                None,
                None,
            )
            .await
        });
        tokio::time::sleep(std::time::Duration::from_millis(30)).await;
        token.cancel();
        let result = run.await.unwrap();
        assert!(matches!(result, Err(AgentLoopError::Cancelled)));

        let events = events(&dir);
        let close_reasons: Vec<Option<String>> = events
            .iter()
            .filter(|e| e.event_type == EventType::RetrievalCloseRecord)
            .map(|e| {
                e.payload
                    .get("terminal_reason")
                    .and_then(|v| v.as_str())
                    .map(str::to_string)
            })
            .collect();
        // The cancel may land before or during the subagent round — either
        // way exactly ONE close per activation, with a cancel-family reason.
        assert_eq!(close_reasons.len(), 1, "{close_reasons:?}");
        assert!(
            close_reasons[0].as_deref() == Some("user_cancelled")
                || close_reasons[0].as_deref() == Some("subagent_cancelled"),
            "{close_reasons:?}"
        );
        // The close precedes the run terminal.
        let close_idx = events
            .iter()
            .position(|e| e.event_type == EventType::RetrievalCloseRecord)
            .unwrap();
        let cancel_idx = events
            .iter()
            .position(|e| e.event_type == EventType::RunCancelled)
            .unwrap();
        assert!(close_idx < cancel_idx, "close before run_cancelled");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// M4: budget exhaustion on the subagent loop is a terminal authority —
    /// a partial result is assessed, then the activation closes with
    /// `budget_exhausted` (assessment + digest bound, no disposition).
    #[tokio::test]
    async fn subagent_budget_exhaustion_closes_activation() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ToolResult {
                output: "ok".to_string(),
                exit_code: Some(0),
                output_encoding: None,
                structured: None,
                ..Default::default()
            }),
        };

        // Subagent budget 2: three subagent tool rounds exhaust it, then a
        // final no-tool round reports the partial result.
        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-1")]),
            ScriptedResponse::tool_calls(vec![tool_call("read_file", "call-2")]),
            ScriptedResponse::tool_calls(vec![tool_call("read_file", "call-3")]),
            ScriptedResponse::text("[DOC] a.md\n部分结果"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway))
            .with_max_tool_rounds(2);
        controller
            .run_turn(
                &host,
                "查找项目文档",
                "RUN-BUD",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        // Assessment precedes the close (verifier ordering).
        let assessment_idx = events
            .iter()
            .position(|e| e.event_type == EventType::InformationSufficiencyAssessment)
            .unwrap();
        let close = events
            .iter()
            .find(|e| e.event_type == EventType::RetrievalCloseRecord)
            .expect("budget close record");
        assert_eq!(
            close
                .payload
                .get("terminal_reason")
                .and_then(|v| v.as_str()),
            Some("budget_exhausted")
        );
        assert!(close.payload.get("assessment_id").is_some());
        assert_eq!(
            close.payload.get("validated_disposition_id"),
            Some(&serde_json::Value::Null)
        );
        let close_idx = events
            .iter()
            .position(|e| e.event_type == EventType::RetrievalCloseRecord)
            .unwrap();
        assert!(assessment_idx < close_idx, "assessment before close");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// THIN-HARNESS-REDESIGN R1 (§4.4): auto-close 后每次派发 = 新激活 =
    /// 新预算（F5 的 continue 累积语义随 disposition 往返一并退役）。
    /// 两次派发各耗 2 个子代理工具轮（< 4），都不触顶、都形成结果并
    /// auto_close——验证"新激活从 0 起算"（若沿用旧累积语义，第二次会
    /// 在累计 4 轮时 budget_exhausted）。
    #[tokio::test]
    async fn subagent_budget_is_fresh_per_dispatch() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ToolResult {
                output: "ok".to_string(),
                exit_code: Some(0),
                output_encoding: None,
                structured: None,
                ..Default::default()
            }),
        };

        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-1")]),
            ScriptedResponse::tool_calls(vec![tool_call("read_file", "call-s1")]),
            ScriptedResponse::tool_calls(vec![tool_call("read_file", "call-s2")]),
            ScriptedResponse::text("[DOC] a.md\n第一批"),
            ScriptedResponse::tool_calls(vec![tool_call("retrieve_project_docs", "call-2")]),
            ScriptedResponse::tool_calls(vec![tool_call("read_file", "call-s3")]),
            ScriptedResponse::tool_calls(vec![tool_call("read_file", "call-s4")]),
            ScriptedResponse::text("[DOC] b.md\n第二批"),
            ScriptedResponse::text("完成"),
            // The main's final answer crosses the counterexample gate —
            // one extra model round answers it (run-semantic; the
            // subagent lanes never fire the gate).
            ScriptedResponse::text("完成"),
        ]));
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway))
            .with_max_tool_rounds(4);
        controller
            .run_turn(
                &host,
                "查找项目文档",
                "RUN-BUDACC",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        // 新预算语义：两次派发均 < 4，无 tool_rounds_limit 门触发。
        assert!(
            !events.iter().any(|e| {
                e.event_type == EventType::GateDecision
                    && e.payload.get("gate").and_then(|v| v.as_str()) == Some("tool_rounds_limit")
            }),
            "fresh per-dispatch budget must not trip the limit: {:?}",
            event_types(&dir)
        );
        // 两次派发均形成结果——revision 0（无 continue 递增）。
        let assessments: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::InformationSufficiencyAssessment)
            .collect();
        assert_eq!(assessments.len(), 2, "{:?}", event_types(&dir));
        assert_eq!(
            assessments[0].payload.get("contract_revision"),
            Some(&serde_json::json!(0))
        );
        assert_eq!(
            assessments[1].payload.get("contract_revision"),
            Some(&serde_json::json!(0))
        );
        // 两条 auto_close close record。
        let closes: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::RetrievalCloseRecord)
            .collect();
        assert_eq!(closes.len(), 2, "{:?}", event_types(&dir));
        assert!(closes.iter().all(|c| {
            c.payload.get("terminal_reason").and_then(|v| v.as_str()) == Some("auto_close")
        }));
        // 两次派发各执行 2 个 read_file（共 4 个，均成功）。
        assert_eq!(
            events
                .iter()
                .filter(|e| {
                    e.event_type == EventType::ToolCompleted
                        && e.payload.get("tool").and_then(|v| v.as_str()) == Some("read_file")
                        && e.payload.get("exit_code") == Some(&serde_json::json!(0))
                })
                .count(),
            4
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    // ── M5 (2026-08-10): orientation lane feeding + Diagnostic Coverage ────

    /// The subagent's completed model rounds feed the internal lane — 7
    /// rounds cross the threshold and fire an `orientation_checkpoint` with
    /// `agent_role=internal_retrieval`, injected into the SUBAGENT
    /// conversation (ADR-0010 §4.2).
    #[tokio::test]
    async fn subagent_lane_feeds_and_fires_orientation() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ToolResult {
                output: "ok".to_string(),
                exit_code: Some(0),
                output_encoding: None,
                structured: None,
                ..Default::default()
            }),
        };

        // The subagent runs 7 read_file tool rounds (7 feeds), then a text
        // round forms the result; the main wraps it with 3 rounds total.
        let mut script = vec![ScriptedResponse::tool_calls(vec![tool_call(
            "retrieve_project_docs",
            "call-1",
        )])];
        for i in 0..7 {
            script.push(ScriptedResponse::tool_calls(vec![tool_call(
                "read_file",
                &format!("call-s{i}"),
            )]));
        }
        script.push(ScriptedResponse::text("[DOC] doc.md\n检索完成"));
        script.push(ScriptedResponse::text("完成"));
        script.push(ScriptedResponse::text("完成"));
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(Arc::new(
            FakeProvider::new(script),
        )));
        let mut orientation =
            crate::orientation::OrientationSessionState::new_with_threshold("sess-lane1234567", 7);
        controller
            .run_turn(
                &host,
                "查找项目文档",
                "RUN-LANE",
                MANIFEST,
                0,
                None,
                Some(&mut orientation),
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        let fires: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::OrientationCheckpoint)
            .collect();
        assert_eq!(fires.len(), 1, "{:?}", event_types(&dir));
        let p = &fires[0].payload;
        assert_eq!(
            p.get("agent_role").and_then(|v| v.as_str()),
            Some("internal_retrieval")
        );
        assert_eq!(
            p.get("trigger").and_then(|v| v.as_str()),
            Some("completed_turns_interval")
        );
        assert_eq!(
            p.get("completed_turns_since_orientation"),
            Some(&serde_json::json!(7))
        );
        assert_eq!(
            p.get("injection_position").and_then(|v| v.as_str()),
            Some("post_tool_batch_gap")
        );
        assert!(
            p.get("message_block")
                .and_then(|v| v.as_str())
                .unwrap()
                .starts_with("[ORIENTATION")
        );
        // Lanes count independently: the main's 3 rounds never fed the
        // subagent lane and vice versa. The fire COMMIT reset the internal
        // lane (7 → 0); the 8th (result-forming) round re-fed it to 1.
        assert_eq!(orientation.internal.completed_rounds, 1);
        assert_eq!(orientation.main.completed_rounds, 3);
        assert_eq!(orientation.external.completed_rounds, 0);
        // §14.16 检索车道不变: the subagent lane keeps the legacy
        // fire-and-continue behavior — no forced template round, no
        // `checkpoint_response` event.
        assert!(
            events
                .iter()
                .all(|e| e.event_type != EventType::CheckpointResponse),
            "retrieval lanes must not produce checkpoint_response events"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A host whose fixed test runner returns scripted results — the DC
    /// hard-signal source (ADR-0010 §4.6.2).
    struct ScriptedTestRunnerHost {
        journal: JournalRecorder,
        results: std::sync::Mutex<std::collections::VecDeque<crate::host::TestRunResult>>,
    }
    #[async_trait]
    impl LoopHost for ScriptedTestRunnerHost {
        fn journal(&self) -> &JournalRecorder {
            &self.journal
        }
        fn tools_registry(&self) -> &dyn ToolRegistry {
            &FullRegistry
        }
        fn tool_policy(&self) -> crate::host::ToolPolicy {
            crate::host::ToolPolicy::Benchmark
        }
        fn test_runner(&self) -> Option<crate::host::TestRunner> {
            Some(crate::host::TestRunner {
                command: vec!["pytest-stub".to_string()],
                timeout: None,
                env: Vec::new(),
            })
        }
        async fn run_tests(&self) -> Result<crate::host::TestRunResult, ToolError> {
            let r = self
                .results
                .lock()
                .unwrap()
                .pop_front()
                .expect("scripted test results exhausted");
            Ok(r)
        }
        async fn request_permission(
            &self,
            _risk: RiskClass,
            _tool: &str,
            _args: &serde_json::Value,
        ) -> Result<PermitDecision, PermitError> {
            // RT-001 (2026-08-11): run_tests passes the permission gate —
            // this host models the Benchmark (harness) policy, where the
            // bridge auto-allows LocalMutation non-shell tools.
            Ok(PermitDecision::AllowOnce)
        }
    }

    fn failing_test_run() -> crate::host::TestRunResult {
        crate::host::TestRunResult {
            output: "FAILED tests/test_x.py::test_y".to_string(),
            exit_code: Some(1),
            full_output_path: Some("D:/test-output.txt".to_string()),
            ..Default::default()
        }
    }
    fn passing_test_run() -> crate::host::TestRunResult {
        crate::host::TestRunResult {
            output: "1 passed".to_string(),
            exit_code: Some(0),
            full_output_path: Some("D:/test-output.txt".to_string()),
            ..Default::default()
        }
    }

    /// ORZ-ORIENTATION-FORCED-TEMPLATE (2026-08-15, ADR-0010 §14.16): a
    /// valid JSON template answer for a forced checkpoint round.
    fn template_answer(next_action: &str) -> ScriptedResponse {
        ScriptedResponse::text(format!(
            r#"{{"task_position":"修复测试失败","progress_evidence":[],"blockers":[],"next_action":"{next_action}","changed_direction":false}}"#
        ))
    }

    /// DC: the threshold progresses 2 → 3 (each fire clears the count), the
    /// checkpoint carries the mechanical payload, and the run continues
    /// past the forced-template checkpoint rounds. The checkpoint answer
    /// rounds count toward the orientation seven-round counter like any
    /// round; each fire is answered by an accepted template round.
    #[tokio::test]
    async fn dc_threshold_progresses_and_fires_mechanical_checkpoint() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = ScriptedTestRunnerHost {
            journal,
            results: std::sync::Mutex::new(
                vec![failing_test_run(), failing_test_run(), failing_test_run()].into(),
            ),
        };
        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t1")]),
            template_answer("continue"),
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t2")]),
            template_answer("continue"),
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t3")]),
            template_answer("continue"),
            ScriptedResponse::text("根据失败继续修复"),
            ScriptedResponse::text("修复完成。"),
        ]));
        let controller = AgentLoopController::with_gateway(gateway);
        let mut orientation =
            crate::orientation::OrientationSessionState::new_with_threshold("sess-dc12345678", 7);
        controller
            .run_turn(
                &host,
                "修复测试失败",
                "RUN-DC",
                MANIFEST,
                0,
                None,
                Some(&mut orientation),
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        let checkpoints: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::DiagnosticCoverageCheckpoint)
            .collect();
        // Each failing call yields 2 signals (the failure fingerprint +
        // the error class): call 1 (2 signals) ≥ threshold 2 → fire; calls
        // 2+3 (4 signals) ≥ threshold 3 → fire. 5 tool rounds total.
        assert_eq!(checkpoints.len(), 2, "{:?}", event_types(&dir));
        let p0 = &checkpoints[0].payload;
        let p1 = &checkpoints[1].payload;
        assert_eq!(p0.get("threshold_stage"), Some(&serde_json::json!(2)));
        assert_eq!(p1.get("threshold_stage"), Some(&serde_json::json!(3)));
        assert_eq!(p0.get("trigger_count"), Some(&serde_json::json!(0)));
        assert_eq!(p1.get("trigger_count"), Some(&serde_json::json!(1)));
        assert_eq!(
            p0.get("inquiry_family").and_then(|v| v.as_str()),
            Some("neutral")
        );
        assert_eq!(
            p0.get("inquiry_kind").and_then(|v| v.as_str()),
            Some("diagnostic_coverage_checkpoint")
        );
        assert!(
            p0.get("signals")
                .and_then(|v| v.as_array())
                .is_some_and(|a| !a.is_empty())
        );
        assert!(
            p0.get("message_block")
                .and_then(|v| v.as_str())
                .unwrap()
                .starts_with("[DIAGNOSTIC_COVERAGE")
        );
        // §14.16: every DC fire is answered by an accepted template round.
        let responses: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::CheckpointResponse)
            .collect();
        assert_eq!(responses.len(), 2, "{:?}", event_types(&dir));
        for r in &responses {
            assert_eq!(
                r.payload.get("inquiry_kind").and_then(|v| v.as_str()),
                Some("diagnostic_coverage_checkpoint")
            );
            assert_eq!(
                r.payload.get("outcome").and_then(|v| v.as_str()),
                Some("accepted")
            );
            assert_eq!(r.payload.get("attempt").and_then(|v| v.as_u64()), Some(1));
        }
        // The run CONTINUED past the checkpoint rounds and the checkpoint
        // answer rounds counted toward the orientation counter: 7 completed
        // main rounds, no orientation fire (the 7-round crossing lands on
        // the final answer round and the loop breaks before the next
        // loop-top — §4.2 count persists to the next run).
        assert_eq!(
            events.last().unwrap().event_type,
            EventType::RunFinished,
            "run continues past the checkpoint"
        );
        assert_eq!(orientation.main.completed_rounds, 7);

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// DC: each stage fires exactly once — after a fire, the count resets
    /// and the NEXT fire needs the next threshold (2 → 3).
    #[tokio::test]
    async fn dc_fires_once_per_stage() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = ScriptedTestRunnerHost {
            journal,
            results: std::sync::Mutex::new(vec![failing_test_run(), failing_test_run()].into()),
        };
        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t1")]),
            template_answer("continue"),
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t2")]),
            template_answer("continue"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        let controller = AgentLoopController::with_gateway(gateway);
        controller
            .run_turn(
                &host,
                "修复测试失败",
                "RUN-DC2",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let checkpoints: Vec<_> = events(&dir)
            .into_iter()
            .filter(|e| e.event_type == EventType::DiagnosticCoverageCheckpoint)
            .collect();
        // GAP-RETRIEVAL-TOOLS (2026-08-10): each failing run now also
        // produces `key_surface_unexamined` (the FAILED line references
        // tests/test_x.py, never read by the model) — call 1's 3 signals
        // fire at threshold 2, call 2's 3 signals reach threshold 3. Each
        // fire is answered by an accepted forced-template round (§14.16).
        assert_eq!(checkpoints.len(), 2, "{:?}", event_types(&dir));
        assert_eq!(
            checkpoints[0].payload.get("threshold_stage"),
            Some(&serde_json::json!(2))
        );
        assert_eq!(
            checkpoints[1].payload.get("threshold_stage"),
            Some(&serde_json::json!(3))
        );
        let responses: Vec<_> = events(&dir)
            .into_iter()
            .filter(|e| e.event_type == EventType::CheckpointResponse)
            .collect();
        assert_eq!(responses.len(), 2);
        assert!(
            responses
                .iter()
                .all(|r| r.payload["outcome"] == serde_json::json!("accepted"))
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// DC: a passing test suite is mechanically-verifiable bug resolution —
    /// the threshold resets to 2 and the next failures fire again at 2.
    #[tokio::test]
    async fn dc_resolves_on_tests_pass_reset_to_2() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = ScriptedTestRunnerHost {
            journal,
            results: std::sync::Mutex::new(
                vec![
                    failing_test_run(),
                    failing_test_run(),
                    passing_test_run(),
                    failing_test_run(),
                    failing_test_run(),
                ]
                .into(),
            ),
        };
        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t1")]),
            template_answer("continue"),
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t2")]),
            template_answer("continue"),
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t3")]),
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t4")]),
            template_answer("continue"),
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t5")]),
            template_answer("continue"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        let controller = AgentLoopController::with_gateway(gateway);
        controller
            .run_turn(
                &host,
                "修复测试失败",
                "RUN-DC3",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let checkpoints: Vec<_> = events(&dir)
            .into_iter()
            .filter(|e| e.event_type == EventType::DiagnosticCoverageCheckpoint)
            .collect();
        // fail ×2 (3 signals each — incl. key_surface_unexamined) → fire at
        // 2 and 3; pass → reset to 2; fail ×2 → fire at 2 and 3 again. Each
        // fire is answered by an accepted forced-template round (§14.16).
        let stages: Vec<u32> = checkpoints
            .iter()
            .map(|c| c.payload["threshold_stage"].as_u64().unwrap() as u32)
            .collect();
        assert_eq!(stages, vec![2, 3, 2, 3], "{stages:?}");

        let _ = std::fs::remove_dir_all(&dir);
    }

    // ── ORZ-ORIENTATION-FORCED-TEMPLATE (2026-08-15, ADR-0010 §14.16) ─────

    /// THIN-HARNESS-REDESIGN-V2 §9.2 (2026-08-29 软门): 7 轮跨越阈值时
    /// 注入简短 [ORIENTATION v0.4] 块并延迟 commit；触发后的纯文本回答被
    /// 消费（loop 明确续跑，不再被当终答），不产生 checkpoint_response、
    /// 不强制无工具轮；终答只由模型自发。
    #[tokio::test]
    async fn orientation_soft_gate_consumes_text_answer_and_continues() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ToolResult {
                output: "ok".to_string(),
                exit_code: Some(0),
                output_encoding: None,
                structured: None,
                ..Default::default()
            }),
        };
        let mut script = Vec::new();
        for i in 0..7 {
            script.push(ScriptedResponse::tool_calls(vec![tool_call(
                "read_file",
                &format!("call-{i}"),
            )]));
        }
        // 触发后的第一轮：纯文本回答被软消费（续跑），不计为终答。
        script.push(ScriptedResponse::text("完成"));
        // 反例门轮 + 最终答案轮。
        script.push(ScriptedResponse::text("完成"));
        script.push(ScriptedResponse::text("完成"));
        let controller = AgentLoopController::with_gateway(Arc::new(FakeProvider::new(script)));
        let mut orientation =
            crate::orientation::OrientationSessionState::new_with_threshold("sess-template1", 7);
        controller
            .run_turn(
                &host,
                "任务",
                "RUN-TPL1",
                MANIFEST,
                0,
                None,
                Some(&mut orientation),
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        let fires: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::OrientationCheckpoint)
            .collect();
        assert_eq!(fires.len(), 1, "{:?}", event_types(&dir));
        assert_eq!(
            fires[0].payload["injection_position"].as_str(),
            Some("post_tool_batch_gap")
        );
        assert_eq!(
            fires[0]
                .payload
                .get("completed_turns_since_orientation")
                .and_then(|v| v.as_u64()),
            Some(7)
        );
        // 无 checkpoint_response——不再有强制模板轮。
        let responses: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::CheckpointResponse)
            .collect();
        assert_eq!(responses.len(), 0, "{:?}", event_types(&dir));
        // 软门延迟 commit：第 8 轮（纯文本回答）feed 后 commit 归 0；
        // 反例门轮 + 最终答案轮再喂 2。
        assert_eq!(orientation.main.completed_rounds, 2);
        assert_eq!(
            events.last().unwrap().event_type,
            EventType::RunFinished,
            "the pure-text answer was consumed and the run continues"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// THIN-HARNESS-REDESIGN-V2 §9.2 (2026-08-29 软门): 触发后下一轮
    /// 仍是普通工具轮——orientation 不禁工具，read_file 调用照常执行。
    #[tokio::test]
    async fn orientation_fire_does_not_force_tool_free_round() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ToolResult {
                output: "ok".to_string(),
                exit_code: Some(0),
                output_encoding: None,
                structured: None,
                ..Default::default()
            }),
        };
        let mut script = Vec::new();
        for i in 0..7 {
            script.push(ScriptedResponse::tool_calls(vec![tool_call(
                "read_file",
                &format!("call-{i}"),
            )]));
        }
        // Fire 后的下一轮：普通工具轮（read_file call-7）直接执行
        // （软门消费点 commit 后落入常规派发路径）。
        script.push(ScriptedResponse::tool_calls(vec![tool_call(
            "read_file",
            "call-7",
        )]));
        script.push(ScriptedResponse::text("完成"));
        script.push(ScriptedResponse::text("完成"));
        let controller = AgentLoopController::with_gateway(Arc::new(FakeProvider::new(script)));
        let mut orientation =
            crate::orientation::OrientationSessionState::new_with_threshold("sess-template2", 7);
        controller
            .run_turn(
                &host,
                "任务",
                "RUN-TPL2",
                MANIFEST,
                0,
                None,
                Some(&mut orientation),
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        // 无 checkpoint_response（软门不产生模板响应事件）。
        assert_eq!(
            events
                .iter()
                .filter(|e| e.event_type == EventType::CheckpointResponse)
                .count(),
            0,
            "{:?}",
            event_types(&dir)
        );
        // Fire 后的 read_file call-7 正常执行（ToolStarted + ToolCompleted）。
        let fire_idx = events
            .iter()
            .position(|e| e.event_type == EventType::OrientationCheckpoint)
            .expect("orientation fire");
        let started_idx = events
            .iter()
            .position(|e| {
                e.event_type == EventType::ToolStarted
                    && e.payload.get("call_id").and_then(|v| v.as_str()) == Some("call-7")
            })
            .expect("post-fire tool round must execute");
        assert!(
            started_idx > fire_idx,
            "the tool round after the fire must execute normally"
        );
        // 延迟 commit：第 8 轮（call-7 工具轮）feed 后 commit 归 0；
        // 反例门轮 + 最终答案轮再喂 2。
        assert_eq!(orientation.main.completed_rounds, 2);
        assert_eq!(events.last().unwrap().event_type, EventType::RunFinished);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// THIN-HARNESS-REDESIGN-V2 §9.2 (2026-08-29 S5-1 修复 B 回归):
    /// orientation 软门触发轮的模型可见工具栏保持常规投影——实机
    /// make-doom / gcode-to-text / video-processing 触发轮工具面为空
    /// （`pending_checkpoint.is_some() → Vec::new()`），模型只能把 XML
    /// 工具调用写成纯文本，浪费一轮真实工作；修复后触发轮请求必须携带
    /// 完整工具列表（含 read_file），模型可回答后继续、也可直接动作。
    #[tokio::test]
    async fn orientation_trigger_round_keeps_tool_face_projected() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ToolResult {
                output: "ok".to_string(),
                exit_code: Some(0),
                output_encoding: None,
                structured: None,
                ..Default::default()
            }),
        };
        let mut script = Vec::new();
        for i in 0..7 {
            script.push(ScriptedResponse::tool_calls(vec![tool_call(
                "read_file",
                &format!("call-{i}"),
            )]));
        }
        // 触发轮：工具调用照常执行（软门不禁工具）。
        script.push(ScriptedResponse::tool_calls(vec![tool_call(
            "read_file",
            "call-7",
        )]));
        script.push(ScriptedResponse::text("完成"));
        script.push(ScriptedResponse::text("完成"));
        let fake = Arc::new(FakeProvider::new(script));
        let controller = AgentLoopController::with_gateway(fake.clone());
        let mut orientation =
            crate::orientation::OrientationSessionState::new_with_threshold("sess-tplface", 7);
        controller
            .run_turn(
                &host,
                "任务",
                "RUN-TPLF",
                MANIFEST,
                0,
                None,
                Some(&mut orientation),
                None,
            )
            .await
            .unwrap();

        // 触发轮 = 消息含 [ORIENTATION 注入块的请求；其工具栏必须与
        // 前一普通工具轮完全一致（常规投影），不得因 pending checkpoint
        // 置空——实机工具面为空时模型只能把 XML 工具调用写成纯文本。
        let requests = fake.received_requests();
        let trigger_idx = requests
            .iter()
            .position(|req| {
                req.messages
                    .iter()
                    .any(|m| m.role == Role::User && m.content.starts_with("[ORIENTATION"))
            })
            .unwrap_or_else(|| panic!("no trigger-round request found: {requests:?}"));
        assert!(
            trigger_idx > 0,
            "a normal tool round must precede the trigger"
        );
        let trigger = &requests[trigger_idx];
        let prior = &requests[trigger_idx - 1];
        assert!(
            !trigger.tools.is_empty(),
            "orientation trigger round must keep the tool face projected: {:?}",
            trigger.tools.iter().map(|t| &t.name).collect::<Vec<_>>()
        );
        assert!(
            trigger.tools.len() == prior.tools.len()
                && trigger.tools.iter().all(|t| {
                    prior.tools.iter().any(|p| {
                        p.name == t.name
                            && p.description == t.description
                            && p.parameters == t.parameters
                    })
                }),
            "trigger-round tool face must equal the prior normal round's projection: \
             prior={:?} trigger={:?}",
            prior.tools.iter().map(|t| &t.name).collect::<Vec<_>>(),
            trigger.tools.iter().map(|t| &t.name).collect::<Vec<_>>()
        );
        assert_eq!(
            events(&dir).last().unwrap().event_type,
            EventType::RunFinished
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// DeepSeek thinking-mode replay regression (2026-08-24 real-run
    /// `invalid_request_error`: "reasoning_content in the thinking mode
    /// must be passed back to the API"): checkpoint answers are replayed
    /// with their `reasoning_content` on the refill and every follow-up
    /// request (the checkpoint branch must not drop it).
    ///
    /// THIN-HARNESS-REDESIGN R1 (§4.3): orientation 的强制模板轮退役后，
    /// checkpoint 机制仅剩 DC 车道——本回归测试改用 DC 触发（failing
    /// run_tests → threshold 2 fire → 模板轮重填）。
    #[tokio::test]
    async fn checkpoint_answers_replay_reasoning_content_on_refill_and_followup() {
        let dir = test_dir();
        let host = ScriptedTestRunnerHost {
            journal: JournalRecorder::new(dir.clone()),
            results: std::sync::Mutex::new(vec![failing_test_run()].into()),
        };
        let script = vec![
            // 失败一次 → DC 触发（2 signals ≥ threshold 2）。
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t1")]),
            // Checkpoint attempt 1: invalid template answer WITH reasoning.
            ScriptedResponse::text("根据任务继续").with_reasoning("推理-尝试1"),
            // Checkpoint attempt 2: valid template answer WITH reasoning.
            template_answer("continue").with_reasoning("推理-尝试2"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ];
        let fake = Arc::new(FakeProvider::new(script));
        let controller = AgentLoopController::with_gateway(fake.clone());
        controller
            .run_turn(
                &host,
                "修复测试失败",
                "RUN-R4-REASONING",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let received = fake.received_requests();
        assert!(received.len() >= 4, "{received:?}");
        let mut saw_attempt1 = false;
        let mut saw_attempt2 = false;
        for request in &received {
            for m in &request.messages {
                if m.role == Role::Assistant && m.content == "根据任务继续" {
                    assert_eq!(
                        m.reasoning_content.as_deref(),
                        Some("推理-尝试1"),
                        "attempt-1 replay must keep reasoning: {request:?}"
                    );
                    saw_attempt1 = true;
                }
                if m.role == Role::Assistant && m.content.contains("\"next_action\":\"continue\"") {
                    assert_eq!(
                        m.reasoning_content.as_deref(),
                        Some("推理-尝试2"),
                        "attempt-2 replay must keep reasoning: {request:?}"
                    );
                    saw_attempt2 = true;
                }
            }
        }
        assert!(saw_attempt1, "attempt-1 answer was never replayed");
        assert!(saw_attempt2, "attempt-2 answer was never replayed");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A tool_calls answer during the checkpoint round is a validation
    /// error (`tool_calls_not_allowed`) — nothing executes, one re-fill is
    /// offered, and the accepted answer resumes the run.
    ///
    /// THIN-HARNESS-REDESIGN R1 (§4.3): orientation 的强制模板轮退役后，
    /// 该机制仅剩 DC 车道——本测试改用 DC 触发（failing run_tests →
    /// threshold 2 fire → 模板轮非法工具调用被拒）。
    #[tokio::test]
    async fn checkpoint_round_tool_call_is_refused_without_execution() {
        let dir = test_dir();
        let host = ScriptedTestRunnerHost {
            journal: JournalRecorder::new(dir.clone()),
            results: std::sync::Mutex::new(vec![failing_test_run()].into()),
        };
        let script = vec![
            // 失败一次 → DC 触发。
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t1")]),
            // The checkpoint round illegally requests a tool (the loop
            // offers none) — the call must never execute.
            ScriptedResponse::tool_calls(vec![tool_call("web_search", "call-cp")]),
            template_answer("continue"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ];
        let controller = AgentLoopController::with_gateway(Arc::new(FakeProvider::new(script)));
        controller
            .run_turn(
                &host,
                "修复测试失败",
                "RUN-TPL4",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        let responses: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::CheckpointResponse)
            .collect();
        assert_eq!(responses.len(), 2, "{:?}", event_types(&dir));
        assert_eq!(
            responses[0].payload["outcome"].as_str(),
            Some("refill_requested")
        );
        assert!(
            responses[0].payload["validation"]["errors"]
                .as_array()
                .is_some_and(|errors| errors
                    .iter()
                    .any(|e| e.as_str() == Some("tool_calls_not_allowed")))
        );
        let fire_idx = events
            .iter()
            .position(|e| e.event_type == EventType::DiagnosticCoverageCheckpoint)
            .unwrap();
        let resp_idx = events
            .iter()
            .position(|e| e.event_type == EventType::CheckpointResponse)
            .unwrap();
        assert!(
            !events[fire_idx..=resp_idx]
                .iter()
                .any(|e| e.event_type == EventType::ToolStarted),
            "illegal checkpoint tool call must not execute"
        );
        assert_eq!(events.last().unwrap().event_type, EventType::RunFinished);
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// DC: a degraded template round still commits the stage (threshold
    /// 2→3) — the next fire needs the next threshold (once-per-stage
    /// guarantee survives the forced-template mechanism).
    #[tokio::test]
    async fn dc_forced_template_degrade_commits_stage_and_fires_next() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = ScriptedTestRunnerHost {
            journal,
            results: std::sync::Mutex::new(vec![failing_test_run(), failing_test_run()].into()),
        };
        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t1")]),
            ScriptedResponse::text("无法填写模板"),
            ScriptedResponse::text("仍然无法填写模板"),
            ScriptedResponse::tool_calls(vec![tool_call("run_tests", "call-t2")]),
            template_answer("continue"),
            ScriptedResponse::text("完成"),
            ScriptedResponse::text("完成"),
        ]));
        let controller = AgentLoopController::with_gateway(gateway);
        controller
            .run_turn(
                &host,
                "修复测试失败",
                "RUN-DC4",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        let checkpoints: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::DiagnosticCoverageCheckpoint)
            .collect();
        assert_eq!(checkpoints.len(), 2, "{:?}", event_types(&dir));
        assert_eq!(checkpoints[0].payload["threshold_stage"].as_u64(), Some(2));
        assert_eq!(checkpoints[1].payload["threshold_stage"].as_u64(), Some(3));
        let responses: Vec<_> = events
            .iter()
            .filter(|e| e.event_type == EventType::CheckpointResponse)
            .collect();
        assert_eq!(responses.len(), 3, "{:?}", event_types(&dir));
        assert_eq!(
            responses[0].payload["outcome"].as_str(),
            Some("refill_requested")
        );
        assert_eq!(responses[1].payload["outcome"].as_str(), Some("degraded"));
        assert_eq!(responses[2].payload["outcome"].as_str(), Some("accepted"));
        assert_eq!(events.last().unwrap().event_type, EventType::RunFinished);
        let _ = std::fs::remove_dir_all(&dir);
    }

    // ── D-9 (FIX_PLAN 2026-08-06): run_tests feedback loop ────────────────

    /// A host exposing a fixed test runner.
    struct TestRunnerHost {
        journal: JournalRecorder,
    }
    #[async_trait]
    impl LoopHost for TestRunnerHost {
        fn journal(&self) -> &JournalRecorder {
            &self.journal
        }
        fn tools_registry(&self) -> &dyn ToolRegistry {
            &FullRegistry
        }
        fn tool_policy(&self) -> crate::host::ToolPolicy {
            crate::host::ToolPolicy::Benchmark
        }
        fn test_runner(&self) -> Option<crate::host::TestRunner> {
            Some(crate::host::TestRunner {
                command: vec!["pytest-stub".to_string()],
                timeout: None,
                env: Vec::new(),
            })
        }
        async fn run_tests(&self) -> Result<crate::host::TestRunResult, ToolError> {
            Ok(crate::host::TestRunResult {
                output: "1 passed".to_string(),
                exit_code: Some(0),
                full_output_path: Some("D:/test-output.txt".to_string()),
                ..Default::default()
            })
        }
        async fn request_permission(
            &self,
            _risk: RiskClass,
            _tool: &str,
            _args: &serde_json::Value,
        ) -> Result<PermitDecision, PermitError> {
            // RT-001 (2026-08-11): same as ScriptedTestRunnerHost — this
            // host models the Benchmark (harness) auto-allow policy.
            Ok(PermitDecision::AllowOnce)
        }
        async fn call_tool(
            &self,
            _name: &str,
            _args: serde_json::Value,
            _call_id: &str,
        ) -> Result<ToolResult, ToolError> {
            unreachable!("denied tools never execute");
        }
    }

    /// A registry declaring `run_tests` unconditionally — proves the
    /// work-tool probe, not the registry, is the declaration source
    /// (P0-A step 3).
    struct RunTestsDeclaringRegistry;
    impl ToolRegistry for RunTestsDeclaringRegistry {
        fn get(&self, name: &str) -> Option<ToolDef> {
            (name == "run_tests").then(registry_run_tests_def)
        }
        fn list(&self) -> Vec<ToolDef> {
            vec![registry_run_tests_def()]
        }
    }

    fn registry_run_tests_def() -> ToolDef {
        ToolDef {
            name: "run_tests".to_string(),
            description: "registry run_tests".to_string(),
            parameters: serde_json::json!({"type": "object", "properties": {}}),
        }
    }

    /// A host whose registry declares `run_tests`; runner presence is
    /// configurable to exercise both probe branches (P0-A step 3).
    struct RunTestsRegistryHost {
        journal: JournalRecorder,
        runner: bool,
    }
    #[async_trait]
    impl LoopHost for RunTestsRegistryHost {
        fn journal(&self) -> &JournalRecorder {
            &self.journal
        }
        fn tools_registry(&self) -> &dyn ToolRegistry {
            &RunTestsDeclaringRegistry
        }
        fn test_runner(&self) -> Option<crate::host::TestRunner> {
            self.runner.then(|| crate::host::TestRunner {
                command: vec!["pytest-stub".to_string()],
                timeout: None,
                env: Vec::new(),
            })
        }
        async fn request_permission(
            &self,
            _risk: RiskClass,
            _tool: &str,
            _args: &serde_json::Value,
        ) -> Result<PermitDecision, PermitError> {
            // The race-call test needs the call to reach the run_tests
            // dispatch branch (permission already approved); the text-only
            // projection tests never invoke this.
            Ok(PermitDecision::AllowOnce)
        }
    }

    /// P0-A step 3: without a host test runner the work-tool probe marks
    /// `run_tests` incomplete (`缺少测试运行器`) and the tool is NOT
    /// declared even when the registry lists it — the probe, not the
    /// registry, is the declaration source.
    #[tokio::test]
    async fn run_tests_removed_when_runner_absent_despite_registry_declaration() {
        let dir = test_dir();
        let host = RunTestsRegistryHost {
            journal: JournalRecorder::new(dir.clone()),
            runner: false,
        };
        let fake = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::text("直接回答"),
            ScriptedResponse::text("完成"),
        ]));
        let gateway: Arc<dyn ModelGateway> = fake.clone();
        let controller = AgentLoopController::with_gateway(gateway);
        controller
            .run_turn(&host, "hi", "RUN-RT-ABSENT", MANIFEST, 0, None, None, None)
            .await
            .unwrap();
        let received = fake.received_requests();
        let declared: Vec<&str> = received[0].tools.iter().map(|t| t.name.as_str()).collect();
        assert!(
            !declared.iter().any(|t| *t == "run_tests"),
            "run_tests must not be declared without a runner: {declared:?}"
        );
        let all_events = events(&dir);
        let availability = all_events
            .iter()
            .find(|e| e.event_type == EventType::ToolAvailabilityCheck)
            .unwrap();
        assert!(
            availability.payload["incomplete"]
                .as_array()
                .unwrap()
                .iter()
                .any(|v| v["tool"] == "run_tests" && v["reason"] == "缺少测试运行器"),
            "probe incomplete reasons: {:?}",
            availability.payload["incomplete"]
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

