    /// THIN-HARNESS-REDESIGN R1 (§4.1)：主车道投影保留保留集内的检索
    /// 工具（web_search / web_fetch / browser_read —— 非工作工具不参与
    /// 探针过滤），且绝不发明已删除工具（retrieve_project_docs /
    /// list_dir / run_tests 等）。
    #[test]
    fn main_lane_projection_keeps_retained_retrieval_only() {
        let base = [
            "read_file",
            "web_search",
            "web_fetch",
            "browser_read",
            "bash",
        ]
        .iter()
        .map(|n| ToolDef {
            name: n.to_string(),
            description: format!("tool {n}"),
            parameters: serde_json::json!({}),
        })
        .collect::<Vec<_>>();
        let snapshot = crate::tool_probe::ToolProbeSnapshot {
            complete: vec!["read_file".to_string()],
            incomplete: vec![],
        };
        let projected = AgentLoopController::project_main_agent_tool_defs(&base, &snapshot);
        let names: Vec<&str> = projected.iter().map(|t| t.name.as_str()).collect();
        for tool in ["web_search", "web_fetch", "browser_read"] {
            assert!(
                names.contains(&tool),
                "retrieval tool {tool} must be declared on the direct surface: {names:?}"
            );
        }
        for retired in [
            "retrieve_project_docs",
            "list_dir",
            "run_tests",
            "todo_write",
        ] {
            assert!(
                !names.contains(&retired),
                "retired tool {retired} must not be invented by the projection: {names:?}"
            );
        }
    }

    // ── MECHANICAL-AUDIT-LAYER 审查处理 (2026-08-24, ADR-0010 §14.39):
    //    direct 面 read-anchor 写前核证 + 退役工具调用面窄门 ────────────

    /// P1-1 (审查处理): direct 面 `search_replace` 携带错误 `expected_anchor`
    /// → 执行前机械拒绝（content_anchor_mismatch、无 ToolStarted、零编辑），
    /// 审计层记录锚点拒单异常事实。
    #[tokio::test]
    async fn direct_search_replace_wrong_anchor_refuses_without_execution() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal: journal.clone(),
            tool_result: Some(ok_result()),
        };
        let target = host.session_cwd().join("anchor_target.txt");
        std::fs::write(&target, "current").unwrap();
        let meta = std::fs::metadata(&target).unwrap();
        let wrong_sha = "0".repeat(64);
        let fake = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![plan_write_call("call-plan-1", valid_plan_json())]),
            ScriptedResponse::tool_calls(vec![ToolCall {
                name: "search_replace".to_string(),
                arguments: serde_json::json!({
                    "file_path": "anchor_target.txt",
                    "old_string": "current",
                    "new_string": "edited",
                    "expected_anchor": {
                        "size": meta.len(),
                        "mtime": meta
                            .modified()
                            .ok()
                            .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                            .map(|d| d.as_secs()),
                        "sha256": wrong_sha,
                    },
                }),
                call_id: "call-edit-1".to_string(),
            }]),
            ScriptedResponse::text("草稿"),
            ScriptedResponse::text("终答"),
        ]));
        let controller = stage_c_controller(fake);
        controller
            .run_turn(
                &host,
                "改文件",
                "RUN-ANCHOR-DIRECT",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        // 零编辑：文件保持原内容，host 工具未被调用。
        assert_eq!(std::fs::read_to_string(&target).unwrap(), "current");
        let r = controller.blackboard().read();
        assert!(
            r.tool_actions.iter().all(|t| t.tool != "search_replace"),
            "{:?}",
            r.tool_actions
        );
        // 事件面：ToolCompleted 拒绝（content_anchor_mismatch），无 ToolStarted。
        let events = events(&dir);
        let refused: Vec<&RunEvent> = events
            .iter()
            .filter(|e| e.event_type == EventType::ToolCompleted)
            .filter(|e| e.payload.get("tool").and_then(|t| t.as_str()) == Some("search_replace"))
            .collect();
        assert_eq!(refused.len(), 1, "{refused:?}");
        assert_eq!(refused[0].payload["exit_code"].as_u64(), Some(1));
        assert_eq!(
            refused[0].payload["error"].as_str(),
            Some("content_anchor_mismatch")
        );
        assert!(
            !events.iter().any(|e| e.event_type == EventType::ToolStarted
                && e.payload.get("tool").and_then(|t| t.as_str()) == Some("search_replace")),
            "no ToolStarted for the refused edit"
        );
        // 审计层：锚点拒单异常事实（结构化 error 透传）。
        let audit: Vec<&RunEvent> = events
            .iter()
            .filter(|e| e.event_type == EventType::MechanicalAuditUpdate)
            .filter(|e| e.payload["kind"] == "tool_result")
            .filter(|e| {
                e.payload["payload"]["key"]
                    .as_str()
                    .unwrap_or_default()
                    .starts_with("file:anchor_target.txt")
            })
            .collect();
        assert!(
            !audit.is_empty(),
            "anchor refusal must be audited: {events:?}"
        );
        assert_eq!(
            audit[0].payload["payload"]["anomaly"].as_str(),
            Some("content_anchor_mismatch")
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// P1-1 (审查处理): direct 面 `search_replace` 携带正确锚点 / 不带锚点
    /// → 照常执行（核证通过或无核证要求）；目标不存在（新建路径）携带锚点
    /// → 跳过核证照常执行。
    #[tokio::test]
    async fn direct_search_replace_anchor_match_or_missing_target_executes() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal: journal.clone(),
            tool_result: Some(ok_result()),
        };
        let target = host.session_cwd().join("anchor_match.txt");
        std::fs::write(&target, "current").unwrap();
        let bytes = std::fs::read(&target).unwrap();
        let meta = std::fs::metadata(&target).unwrap();
        let sha = sha256_hex(&bytes);
        let fake = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![plan_write_call("call-plan-1", valid_plan_json())]),
            // 同批三次调用：正确锚点 / 无锚点 / 目标不存在（新建路径）。
            ScriptedResponse::tool_calls(vec![
                ToolCall {
                    name: "search_replace".to_string(),
                    arguments: serde_json::json!({
                        "file_path": "anchor_match.txt",
                        "old_string": "current",
                        "new_string": "edited",
                        "expected_anchor": {
                            "size": meta.len(),
                            "mtime": meta
                                .modified()
                                .ok()
                                .and_then(|t| t.duration_since(std::time::UNIX_EPOCH).ok())
                                .map(|d| d.as_secs()),
                            "sha256": sha,
                        },
                    }),
                    call_id: "call-edit-match".to_string(),
                },
                ToolCall {
                    name: "search_replace".to_string(),
                    arguments: serde_json::json!({
                        "file_path": "anchor_match.txt",
                        "old_string": "current",
                        "new_string": "edited",
                    }),
                    call_id: "call-edit-noanchor".to_string(),
                },
                ToolCall {
                    name: "search_replace".to_string(),
                    arguments: serde_json::json!({
                        "file_path": "brand_new.txt",
                        "old_string": "",
                        "new_string": "content",
                        "expected_anchor": {
                            "size": 0,
                            "sha256": "0".repeat(64),
                        },
                    }),
                    call_id: "call-edit-new".to_string(),
                },
            ]),
            ScriptedResponse::text("草稿"),
            // COUNTEREXAMPLE_GATE 终答前一次反例自查注入占一轮模型回答。
            ScriptedResponse::text("草稿（反例自查）。"),
            ScriptedResponse::text("终答"),
        ]));
        let controller = stage_c_controller(fake);
        controller
            .run_turn(
                &host,
                "改文件",
                "RUN-ANCHOR-OK",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        let completed: Vec<&RunEvent> = events
            .iter()
            .filter(|e| e.event_type == EventType::ToolCompleted)
            .filter(|e| e.payload.get("tool").and_then(|t| t.as_str()) == Some("search_replace"))
            .collect();
        assert_eq!(completed.len(), 3, "{completed:?}");
        assert!(
            completed
                .iter()
                .all(|e| e.payload["exit_code"].as_u64() == Some(0)),
            "{completed:?}"
        );
        assert!(
            !events.iter().any(|e| {
                e.event_type == EventType::ToolCompleted
                    && e.payload.get("error").and_then(|v| v.as_str())
                        == Some("content_anchor_mismatch")
            }),
            "no anchor refusal on the matching path"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// P1-2 (审查处理): 三个退役 console 订单工具（blackboard_action_write /
    /// console_step_done / console_return_to_console）在调用面被机械拒绝——
    /// 零 ToolStarted、零 console_order_written 事件、动作栏无订单残留、
    /// run 正常完成。
    #[tokio::test]
    async fn retired_console_tools_refused_with_zero_side_effects() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ok_result()),
        };
        let fake = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![plan_write_call("call-plan-1", valid_plan_json())]),
            ScriptedResponse::tool_calls(vec![
                ToolCall {
                    name: "blackboard_action_write".to_string(),
                    arguments: serde_json::json!({
                        "action": "workspace.search_replace",
                        "step_id": "s1",
                        "arguments": {"file_path": "a.txt", "old_string": "v1", "new_string": "v2"},
                    }),
                    call_id: "call-retired-1".to_string(),
                },
                ToolCall {
                    name: "console_step_done".to_string(),
                    arguments: serde_json::json!({
                        "step_id": "s1",
                        "transition_id": "t1",
                        "trace_id": "tr1",
                    }),
                    call_id: "call-retired-2".to_string(),
                },
                ToolCall {
                    name: "console_return_to_console".to_string(),
                    arguments: serde_json::json!({}),
                    call_id: "call-retired-3".to_string(),
                },
            ]),
            ScriptedResponse::text("草稿"),
            ScriptedResponse::text("终答"),
        ]));
        let controller = stage_c_controller(fake);
        controller
            .run_turn(
                &host,
                "幻觉调用退役工具",
                "RUN-RETIRED",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        for name in [
            "blackboard_action_write",
            "console_step_done",
            "console_return_to_console",
        ] {
            let completed: Vec<&RunEvent> = events
                .iter()
                .filter(|e| e.event_type == EventType::ToolCompleted)
                .filter(|e| e.payload.get("tool").and_then(|t| t.as_str()) == Some(name))
                .collect();
            assert_eq!(completed.len(), 1, "{name}: {completed:?}");
            assert_eq!(completed[0].payload["exit_code"].as_u64(), Some(1));
            assert_eq!(
                completed[0].payload["error"].as_str(),
                Some("retired_tool_denied"),
                "{name}"
            );
            assert!(
                !events.iter().any(|e| e.event_type == EventType::ToolStarted
                    && e.payload.get("tool").and_then(|t| t.as_str()) == Some(name)),
                "{name} must never reach ToolStarted"
            );
        }
        // 零订单残留：没有 console_order_written 事件，动作栏无 pending 订单。
        assert!(
            !events
                .iter()
                .any(|e| e.event_type == EventType::ConsoleOrderWritten),
            "retired tools must not produce console orders"
        );
        let r = controller.blackboard().read();
        assert!(r.actions.order.is_none(), "{:?}", r.actions.order);

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// THIN-HARNESS-REDESIGN R1 (§4.1 边界项): 边界三项
    /// `todo_write` / `update_goal` / `compaction_whitelist_add` 调用一律
    /// 结构化拒绝（sealed_tool_denied、无 ToolStarted、零副作用——
    /// whitelist 不落盘、goal 不变）。
    #[tokio::test]
    async fn sealed_boundary_tools_refused_with_zero_side_effects() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ok_result()),
        };
        let fake = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![
                ToolCall {
                    name: "todo_write".to_string(),
                    arguments: serde_json::json!({"todos": [{"content": "x"}]}),
                    call_id: "call-sealed-1".to_string(),
                },
                ToolCall {
                    name: "update_goal".to_string(),
                    arguments: serde_json::json!({"goal": "g"}),
                    call_id: "call-sealed-2".to_string(),
                },
                ToolCall {
                    name: "compaction_whitelist_add".to_string(),
                    arguments: serde_json::json!({"content": "事实"}),
                    call_id: "call-sealed-3".to_string(),
                },
            ]),
            ScriptedResponse::text("草稿"),
            ScriptedResponse::text("终答"),
        ]));
        // R1 审查处理：封存窄门与 console/plan 面无关——用普通控制器
        // （无 plan_first/console）保持测试聚焦于 sealed_tool_denied。
        let controller = AgentLoopController::with_gateway(fake);
        controller
            .run_turn(
                &host,
                "幻觉调用封存工具",
                "RUN-SEALED",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();

        let events = events(&dir);
        for name in ["todo_write", "update_goal", "compaction_whitelist_add"] {
            let completed: Vec<&RunEvent> = events
                .iter()
                .filter(|e| e.event_type == EventType::ToolCompleted)
                .filter(|e| e.payload.get("tool").and_then(|t| t.as_str()) == Some(name))
                .collect();
            assert_eq!(completed.len(), 1, "{name}: {completed:?}");
            assert_eq!(completed[0].payload["exit_code"].as_u64(), Some(1));
            assert_eq!(
                completed[0].payload["error"].as_str(),
                Some("sealed_tool_denied"),
                "{name}"
            );
            assert!(
                !events.iter().any(|e| e.event_type == EventType::ToolStarted
                    && e.payload.get("tool").and_then(|t| t.as_str()) == Some(name)),
                "{name} must never reach ToolStarted"
            );
        }
        // 零副作用：whitelist 空、goal digest 未变（仍为任务 prompt 摘要）。
        let w = controller.whitelist.lock().unwrap();
        assert!(w.is_empty(), "sealed whitelist write must not land: {w:?}");
        drop(w);

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// 设计 §2.3/§2.7/§5 验收 3（派发面）：主车道调用 web_search → relay
    /// 派发检索子代理（ToolStarted target=external_retrieval），子代理车道
    /// 自行执行检索工具（TestHost NotFound 证明到达 host 工具集）。
    #[tokio::test]
    async fn main_lane_web_search_dispatches_to_retrieval_subagent() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };
        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            // 主车道第 1 轮：直接调 web_search。
            ScriptedResponse::tool_calls(vec![tool_call("web_search", "call-w1")]),
            // 子代理车道第 1 轮：自行执行 web_search（lane self-execution）。
            ScriptedResponse::tool_calls(vec![tool_call("web_search", "call-w2")]),
            // 子代理车道第 2 轮：形成检索结果并关闭。
            ScriptedResponse::text("检索完成"),
            // 主车道：终答前反例自查轮 + 终答。
            ScriptedResponse::text("草稿"),
            ScriptedResponse::text("终答"),
        ]));
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway));
        let (response, _, _) = controller
            .run_turn(
                &host,
                "查一下",
                "RUN-RETRIEVAL-MAIN",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();
        assert_eq!(response, "终答");

        let events = events(&dir);
        // 主车道 web_search 派发到 external_retrieval（relay 路由）。
        let dispatch = events
            .iter()
            .find(|e| {
                e.event_type == EventType::ToolStarted
                    && e.payload.get("tool").and_then(serde_json::Value::as_str)
                        == Some("web_search")
                    && e.payload.get("target").and_then(serde_json::Value::as_str)
                        == Some("external_retrieval")
            })
            .expect("web_search dispatched to the external retrieval subagent");
        assert_eq!(dispatch.payload["call_id"], serde_json::json!("call-w1"));
        // 子代理车道实际执行了 web_search（TestHost NotFound 证明到达
        // host 工具集；车道自执行事件不带 target 字段）。
        let subagent_call = events
            .iter()
            .find(|e| {
                e.event_type == EventType::ToolCompleted
                    && e.payload.get("tool").and_then(serde_json::Value::as_str)
                        == Some("web_search")
                    && e.payload.get("call_id").and_then(serde_json::Value::as_str)
                        == Some("call-w2")
            })
            .expect("subagent lane self-executes web_search through the host");
        let err = subagent_call
            .payload
            .get("error")
            .and_then(serde_json::Value::as_str)
            .expect("host failure");
        assert!(
            err.contains("test host has no tool result"),
            "web_search reached the host toolset: {err}"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// RETRIEVAL-SUBAGENT-WIRING (2026-08-25, ADR-0010 §14.40)：主车道
    /// 调 `retrieve_project_docs` → relay 路由到 internal_retrieval
    /// 子代理（内部 lane 工具面仅读族）；子代理多轮检索后返回
    /// `[DOC]` 结构化结果。
    #[tokio::test]
    async fn main_lane_retrieve_project_docs_dispatches_to_internal_subagent() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };
        let fake = Arc::new(FakeProvider::new(vec![
            // 主车道第 1 轮：直接调 retrieve_project_docs。
            // 审查处理：query 必填 + 可选 scope/max_results 一并进入契约。
            ScriptedResponse::tool_calls(vec![ToolCall {
                name: "retrieve_project_docs".to_string(),
                arguments: serde_json::json!({
                    "query": "调研缓存层",
                    "scope": "src/cache",
                    "max_results": 3,
                }),
                call_id: "call-rpd-1".to_string(),
            }]),
            // 子代理车道第 1 轮：调用读族工具（read_file）做检索。
            ScriptedResponse::tool_calls(vec![tool_call("read_file", "call-rpd-2")]),
            // 子代理车道第 2 轮：形成结构化结果并关闭。
            ScriptedResponse::text("[DOC] src/cache.rs 缓存回归定位"),
            // 主车道：终答前反例自查轮 + 终答。
            ScriptedResponse::text("草稿"),
            ScriptedResponse::text("终答"),
        ]));
        let gateway: Arc<dyn ModelGateway> = fake.clone();
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway));
        let (response, _, _) = controller
            .run_turn(
                &host,
                "调研项目文档",
                "RUN-RETRIEVAL-INTERNAL",
                MANIFEST,
                0,
                None,
                None,
                None,
            )
            .await
            .unwrap();
        assert_eq!(response, "终答");

        // 审查处理：scope/max_results 机械并入子代理任务契约（子代理只收
        // goal 文本，声明面承诺的参数必须进契约）。
        let received = fake.received_requests();
        let subagent_req = received
            .iter()
            .find(|r| r.system.contains("调研缓存层"))
            .expect("internal subagent receives the folded retrieval task goal");
        assert!(
            subagent_req.system.contains("scope: src/cache"),
            "scope folded into the subagent contract: {subagent_req:?}"
        );
        assert!(
            subagent_req.system.contains("max_results: 3"),
            "max_results folded into the subagent contract: {subagent_req:?}"
        );

        let events = events(&dir);
        // 主车道 retrieve_project_docs 派发到 internal_retrieval（relay 路由）。
        let dispatch = events
            .iter()
            .find(|e| {
                e.event_type == EventType::ToolStarted
                    && e.payload.get("tool").and_then(serde_json::Value::as_str)
                        == Some("retrieve_project_docs")
                    && e.payload.get("target").and_then(serde_json::Value::as_str)
                        == Some("internal_retrieval")
            })
            .expect("retrieve_project_docs dispatched to the internal retrieval subagent");
        assert_eq!(dispatch.payload["call_id"], serde_json::json!("call-rpd-1"));
        // 子代理车道实际执行了读族工具（TestHost NotFound 证明到达 host
        // 工具集；内部 lane 不含 web 族/browser_read）。
        let subagent_call = events
            .iter()
            .find(|e| {
                e.event_type == EventType::ToolCompleted
                    && e.payload.get("tool").and_then(serde_json::Value::as_str)
                        == Some("read_file")
                    && e.payload.get("call_id").and_then(serde_json::Value::as_str)
                        == Some("call-rpd-2")
            })
            .expect("internal lane executes read-family tool through the host");
        let err = subagent_call
            .payload
            .get("error")
            .and_then(serde_json::Value::as_str)
            .expect("host failure");
        assert!(
            err.contains("test host has no tool result"),
            "read_file reached the host toolset: {err}"
        );
        // 内部 lane 事件面：无 web_search / web_fetch / browser_read 调用。
        assert!(
            !events.iter().any(|e| {
                (e.event_type == EventType::ToolStarted || e.event_type == EventType::ToolCompleted)
                    && e.payload
                        .get("tool")
                        .and_then(serde_json::Value::as_str)
                        .is_some_and(|t| {
                            crate::relay::is_web_retrieval_tool(t) || t == "browser_read"
                        })
            }),
            "internal lane must not touch web/browser tools: {events:?}"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// THIN-HARNESS-REDESIGN R1 (§4.1)：主面声明面不再包含
    /// `retrieve_project_docs` / `retrieval_disposition`（内部子代理与
    /// disposition 仪式退役）与边界三项（todo_write / update_goal /
    /// compaction_whitelist_add）——framework_fallback 与 mode=off 皆然；
    /// （正断言见 r1_main_surface_is_eight_tools——本测试只做负断言，
    /// TestHost 注册面为空。）
    #[tokio::test]
    async fn main_surface_hides_retired_and_sealed_tools() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: Some(ok_result()),
        };
        let fake = Arc::new(FakeProvider::from_texts(vec!["完成", "完成"]));
        let gateway: Arc<dyn ModelGateway> = fake.clone();
        let controller = with_retrieval_enabled(AgentLoopController::with_gateway(gateway));
        controller
            .run_turn(&host, "hi", "RUN-RPD-DECL", MANIFEST, 0, None, None, None)
            .await
            .unwrap();
        let received = fake.received_requests();
        let declared: Vec<&str> = received[0].tools.iter().map(|t| t.name.as_str()).collect();
        for hidden in [
            "retrieve_project_docs",
            "retrieval_disposition",
            "todo_write",
            "update_goal",
            "compaction_whitelist_add",
            "plan_write",
            "list_dir",
            "run_tests",
            "search_tool",
            "pdf_read",
        ] {
            assert!(
                !declared.contains(&hidden),
                "{hidden} must NOT be declared on the direct surface: {declared:?}"
            );
        }
        // mode=off（默认）：检索族整体剔除（含 web 族）。
        let dir2 = test_dir();
        let journal2 = JournalRecorder::new(dir2.clone());
        let host2 = TestHost {
            journal: journal2,
            tool_result: Some(ok_result()),
        };
        let fake2 = Arc::new(FakeProvider::from_texts(vec!["完成", "完成"]));
        let gateway2: Arc<dyn ModelGateway> = fake2.clone();
        let controller2 = AgentLoopController::with_gateway(gateway2);
        controller2
            .run_turn(&host2, "hi", "RUN-RPD-OFF", MANIFEST, 0, None, None, None)
            .await
            .unwrap();
        let received2 = fake2.received_requests();
        let declared2: Vec<&str> = received2[0].tools.iter().map(|t| t.name.as_str()).collect();
        assert!(
            !declared2.iter().any(|t| {
                *t == "retrieve_project_docs"
                    || *t == "retrieval_disposition"
                    || *t == "web_search"
                    || *t == "web_fetch"
            }),
            "retrieval family must be hidden under mode=off: {declared2:?}"
        );

        let _ = std::fs::remove_dir_all(&dir);
        let _ = std::fs::remove_dir_all(&dir2);
    }

    // ── Phase 3 slice #7: cooperative cancellation ─────────────────────────

    /// A pre-cancelled token aborts at the loop-top checkpoint (before any
    /// model round): the journal ends with a valid `run_cancelled` terminal
    /// and never sees a `model_output`.
    #[tokio::test]
    async fn pre_cancelled_token_aborts_run_with_run_cancelled_terminal() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };
        let gateway: Arc<dyn ModelGateway> =
            Arc::new(FakeProvider::from_texts(vec!["结果：完成", "结果：完成"]));
        let controller = AgentLoopController::with_gateway(gateway);
        let token = tokio_util::sync::CancellationToken::new();
        token.cancel();

        let result = controller
            .run_turn_with_cancel(
                &host,
                "hello",
                "RUN-CANCEL",
                MANIFEST,
                0,
                None,
                Some(&token),
                None,
                None,
            )
            .await;

        assert!(matches!(result, Err(AgentLoopError::Cancelled)));
        let types = event_types(&dir);
        assert!(
            !types.contains(&EventType::ModelOutput),
            "cancel at loop top precedes any model round: {types:?}"
        );

        let replay = orz_assurance::replay_journal(
            &dir.join("events.jsonl"),
            Some("RUN-CANCEL"),
            None,
            true,
        );
        assert!(replay.valid, "journal invalid: {:?}", replay.errors);
        assert_eq!(replay.terminal_event.as_deref(), Some("run_cancelled"));
        let cancelled = events(&dir)
            .into_iter()
            .find(|e| e.event_type == EventType::RunCancelled)
            .expect("run_cancelled event");
        assert_eq!(
            cancelled.payload.get("reason").and_then(|r| r.as_str()),
            Some("user_cancelled")
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A cancel landing mid-model-round terminates at the after-round
    /// checkpoint — BEFORE tool dispatch, so no tool ever starts.
    #[tokio::test]
    async fn cancel_mid_round_skips_tool_dispatch() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };
        // First round is a text (slow-chunked so the cancel lands inside the
        // model round); the tool round would come after it — never reached.
        let gateway: Arc<dyn ModelGateway> = Arc::new(
            FakeProvider::new(vec![
                ScriptedResponse::text("准备执行命令。"),
                ScriptedResponse::tool_calls(vec![tool_call("bash", "call-1")]),
                ScriptedResponse::text("结果：完成"),
                ScriptedResponse::text("结果：完成"),
            ])
            .with_chunk_delay(std::time::Duration::from_millis(100)),
        );
        let controller = Arc::new(AgentLoopController::with_gateway(gateway));
        let token = tokio_util::sync::CancellationToken::new();

        let c = controller.clone();
        let t = token.clone();
        let run = tokio::task::spawn(async move {
            c.run_turn_with_cancel(
                &host,
                "执行命令",
                "RUN-CANCEL-2",
                MANIFEST,
                0,
                None,
                Some(&t),
                None,
                None,
            )
            .await
        });
        tokio::time::sleep(std::time::Duration::from_millis(30)).await;
        token.cancel();
        let result = run.await.unwrap();

        assert!(matches!(result, Err(AgentLoopError::Cancelled)));
        let types = event_types(&dir);
        assert!(
            !types.contains(&EventType::ToolStarted),
            "cancel precedes tool dispatch: {types:?}"
        );
        assert!(types.contains(&EventType::RunCancelled), "{types:?}");

        let replay = orz_assurance::replay_journal(
            &dir.join("events.jsonl"),
            Some("RUN-CANCEL-2"),
            None,
            true,
        );
        assert!(replay.valid, "journal invalid: {:?}", replay.errors);
        assert_eq!(replay.terminal_event.as_deref(), Some("run_cancelled"));

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A multi-tool round: a cancel landing while the FIRST tool is still
    /// running must not start the remaining tools — the per-tool checkpoint
    /// (2026-08-05 review P2-2) gates every dispatch, not just the round.
    #[tokio::test]
    async fn cancel_mid_multi_tool_round_skips_unstarted_tools() {
        struct SlowFirstToolHost {
            journal: JournalRecorder,
            release: Arc<Mutex<Option<tokio::sync::mpsc::Receiver<()>>>>,
        }

        #[async_trait]
        impl LoopHost for SlowFirstToolHost {
            fn journal(&self) -> &JournalRecorder {
                &self.journal
            }
            fn tools_registry(&self) -> &dyn ToolRegistry {
                &EmptyRegistry
            }
            async fn request_permission(
                &self,
                _risk: RiskClass,
                _tool: &str,
                _args: &serde_json::Value,
            ) -> Result<PermitDecision, PermitError> {
                Ok(PermitDecision::AllowOnce)
            }
            async fn call_tool(
                &self,
                name: &str,
                _args: serde_json::Value,
                _call_id: &str,
            ) -> Result<ToolResult, ToolError> {
                if name == "bash" {
                    // Block until the test releases — the cancel lands while
                    // tool #1 is in flight.
                    let mut rx = self.release.lock().unwrap().take().unwrap();
                    let _ = rx.recv().await;
                }
                Ok(ToolResult {
                    output: "ok".to_string(),
                    exit_code: None,
                    output_encoding: None,
                    structured: None,
                    ..Default::default()
                })
            }
        }

        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let (release_tx, release_rx) = tokio::sync::mpsc::channel::<()>(1);
        let host = SlowFirstToolHost {
            journal,
            release: Arc::new(Mutex::new(Some(release_rx))),
        };
        // One round with TWO tool calls: bash (slow) + read_file.
        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![
                tool_call("bash", "call-1"),
                tool_call("read_file", "call-2"),
            ]),
            ScriptedResponse::text("结果：完成"),
            ScriptedResponse::text("结果：完成"),
        ]));
        let controller = Arc::new(AgentLoopController::with_gateway(gateway));
        let token = tokio_util::sync::CancellationToken::new();

        let c = controller.clone();
        let t = token.clone();
        let mut run = tokio::task::spawn(async move {
            c.run_turn_with_cancel(
                &host,
                "执行命令",
                "RUN-CANCEL-4",
                MANIFEST,
                0,
                None,
                Some(&t),
                None,
                None,
            )
            .await
        });

        // The run parks inside bash (tool #1 in flight); cancel lands there.
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        token.cancel();
        // Cooperative: the in-flight tool finishes first.
        tokio::select! {
            _ = &mut run => panic!("cancel must not abort the in-flight tool"),
            _ = tokio::time::sleep(std::time::Duration::from_millis(100)) => {}
        }
        let _ = release_tx.send(()).await;
        let result = run.await.unwrap();
        assert!(matches!(result, Err(AgentLoopError::Cancelled)));

        let all_events = events(&dir);
        let types: Vec<EventType> = all_events.iter().map(|e| e.event_type.clone()).collect();
        let started: Vec<&str> = all_events
            .iter()
            .filter(|e| e.event_type == EventType::ToolStarted)
            .filter_map(|e| e.payload.get("tool").and_then(|t| t.as_str()))
            .collect();
        assert_eq!(
            started,
            vec!["bash"],
            "only the in-flight tool starts — read_file must never dispatch: {types:?}"
        );
        assert!(types.contains(&EventType::RunCancelled), "{types:?}");

        let replay = orz_assurance::replay_journal(
            &dir.join("events.jsonl"),
            Some("RUN-CANCEL-4"),
            None,
            true,
        );
        assert!(replay.valid, "journal invalid: {:?}", replay.errors);
        assert_eq!(replay.terminal_event.as_deref(), Some("run_cancelled"));

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// A host whose permission await is gated on an external oneshot: a
    /// cancel during the permission prompt does NOT interrupt it (cooperative
    /// semantics — the permission manager is session-scoped and shared; a
    /// dropped future could orphan its prompt). The run terminates at the
    /// next checkpoint AFTER the permission resolves.
    #[tokio::test]
    async fn cancel_during_permission_await_resolves_then_terminates() {
        struct GatedHost {
            journal: JournalRecorder,
            release: Arc<Mutex<Option<tokio::sync::mpsc::Receiver<()>>>>,
        }

        #[async_trait]
        impl LoopHost for GatedHost {
            fn journal(&self) -> &JournalRecorder {
                &self.journal
            }
            fn tools_registry(&self) -> &dyn ToolRegistry {
                &EmptyRegistry
            }
            async fn request_permission(
                &self,
                _risk: RiskClass,
                _tool: &str,
                _args: &serde_json::Value,
            ) -> Result<PermitDecision, PermitError> {
                // Block until the test sends the release, then deny.
                let mut rx = self.release.lock().unwrap().take().unwrap();
                let _ = rx.recv().await;
                Ok(PermitDecision::Deny)
            }
        }

        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let (release_tx, release_rx) = tokio::sync::mpsc::channel::<()>(1);
        let host = GatedHost {
            journal,
            release: Arc::new(Mutex::new(Some(release_rx))),
        };
        let gateway: Arc<dyn ModelGateway> = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::tool_calls(vec![tool_call("bash", "call-1")]),
            ScriptedResponse::text("结果：完成"),
            ScriptedResponse::text("结果：完成"),
        ]));
        let controller = Arc::new(AgentLoopController::with_gateway(gateway));
        let token = tokio_util::sync::CancellationToken::new();

        let c = controller.clone();
        let t = token.clone();
        let mut run = tokio::task::spawn(async move {
            c.run_turn_with_cancel(
                &host,
                "执行命令",
                "RUN-CANCEL-3",
                MANIFEST,
                0,
                None,
                Some(&t),
                None,
                None,
            )
            .await
        });

        // The run parks at the permission await (tool round reached).
        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
        token.cancel();
        // Cooperative: cancelling does NOT abort the pending permission.
        tokio::select! {
            _ = &mut run => panic!("cancel must not interrupt the permission await"),
            _ = tokio::time::sleep(std::time::Duration::from_millis(100)) => {}
        }
        // Release the gate (deny) — the loop's next checkpoint terminates.
        let _ = release_tx.send(()).await;
        let result = run.await.unwrap();
        assert!(matches!(result, Err(AgentLoopError::Cancelled)));

        let types = event_types(&dir);
        assert!(
            !types.contains(&EventType::ToolStarted),
            "denied tool must not start: {types:?}"
        );
        assert!(types.contains(&EventType::PermissionRequested), "{types:?}");
        assert!(types.contains(&EventType::RunCancelled), "{types:?}");

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Grill mode (2026-08-08 write-placement slice, design §3): a grill
    /// turn runs the full model↔tool loop with a discard `EventWriter` — no
    /// journal events land on disk, the conversation history is written back
    /// for the next turn, the template is injected once, and the
    /// final-answer counterexample gate is skipped (a grill question is not
    /// a final answer — the gate would force an extra provider round).
    #[tokio::test]
    async fn grill_turn_no_journal_history_and_skips_gate() {
        // Two scripts: if the counterexample gate fired, the model would get
        // a second round and the final response would be the second script.
        let provider = FakeProvider::new(vec![
            ScriptedResponse::text("问题一: 是否考虑……?"),
            ScriptedResponse::text("问题二: 不应到达"),
        ]);
        let controller = AgentLoopController::with_gateway(Arc::new(provider));
        let dir = test_dir();
        let host = TestHost {
            journal: JournalRecorder::new(dir.clone()),
            tool_result: None,
        };

        // Turn 1: template injected once + user input + assistant question.
        let mut history = Vec::new();
        let response = controller
            .run_grill_turn(&host, &mut history, "用户回答一", Some("模板"), None)
            .await
            .unwrap();
        assert_eq!(response, "问题一: 是否考虑……?");
        assert_eq!(history.len(), 3, "template + user input + assistant reply");
        assert_eq!(history[0].content, "模板");
        assert_eq!(history[1].content, "用户回答一");
        assert_eq!(history[2].content, "问题一: 是否考虑……?");

        // Turn 2: no template (session start only), history continues; the
        // provider's second script is consumed normally.
        let response2 = controller
            .run_grill_turn(&host, &mut history, "用户回答二", None, None)
            .await
            .unwrap();
        assert_eq!(response2, "问题二: 不应到达");
        assert_eq!(history.len(), 5);

        // No run journal was touched (bootstrap dirs belong to the host; the
        // controller wrote zero events).
        assert!(
            !dir.join("events.jsonl").exists(),
            "grill turns must not write run-journal events"
        );

        let _ = std::fs::remove_dir_all(&dir);
    }

    /// Grill turns are a model↔tool round — ACAF fail-closed with an
    /// unconfigured fabric must refuse loudly here too (2026-08-16 review
    /// fix P2-I1), matching the `run_turn_with_guards` D-15 startup check
    /// and the ACP server's documented promise.
    #[tokio::test]
    async fn grill_turn_fail_closed_without_fabric_refuses() {
        let provider = FakeProvider::new(vec![ScriptedResponse::text("不应到达")]);
        let controller =
            AgentLoopController::with_gateway(Arc::new(provider)).with_acaf_fail_closed(true);
        let dir = test_dir();
        let host = TestHost {
            journal: JournalRecorder::new(dir.clone()),
            tool_result: None,
        };
        let mut history = Vec::new();
        let err = controller
            .run_grill_turn(&host, &mut history, "问题", None, None)
            .await
            .unwrap_err();
        assert!(
            err.to_string().contains("fail-closed"),
            "unexpected error: {err}"
        );
        assert_eq!(history.len(), 0, "no turn may start without a fabric");
        let _ = std::fs::remove_dir_all(&dir);
    }

    // ── GAP-CONVERSATION-RESTORE (2026-08-10): multi-prompt conversation ──

    fn conv_message(role: Role, content: &str) -> Message {
        Message {
            role,
            content: content.to_string(),
            tool_call_id: None,
            tool_calls: Vec::new(),
            reasoning_content: None,
        }
    }

    /// One complete tool round: an assistant declaration (with a tool call)
    /// plus its tool result — protocol-valid seed material for recovery
    /// truncation tests.
    fn tool_round(call_id: &str, result: &str) -> Vec<Message> {
        vec![
            Message {
                role: Role::Assistant,
                content: String::new(),
                tool_call_id: None,
                tool_calls: vec![ToolCall {
                    name: "read_file".to_string(),
                    arguments: serde_json::json!({"path": result}),
                    call_id: call_id.to_string(),
                }],
                reasoning_content: None,
            },
            Message {
                role: Role::Tool,
                content: result.to_string(),
                tool_call_id: Some(call_id.to_string()),
                tool_calls: Vec::new(),
                reasoning_content: None,
            },
        ]
    }

    /// A valid five-section summary response (mechanical slots are filled
    /// by the controller; only the two model slots matter here).
    /// The conversation seeds the model context (prior history + new prompt)
    /// and the full conversation comes back on success — reasoning content
    /// included (the DeepSeek multi-turn replay requirement).
    #[tokio::test]
    async fn run_turn_conversation_seeds_and_writes_back() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };
        let fake = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::text("收到"),
            ScriptedResponse::text("收到"),
        ]));
        let controller = AgentLoopController::with_gateway(fake.clone());
        let mut conversation = vec![
            conv_message(Role::User, "第一问"),
            Message {
                role: Role::Assistant,
                content: "第一答".to_string(),
                tool_call_id: None,
                tool_calls: Vec::new(),
                reasoning_content: Some("思考过程".to_string()),
            },
        ];
        let response = controller
            .run_turn(
                &host,
                "第二问",
                "RUN-CONV",
                MANIFEST,
                0,
                None,
                None,
                Some(&mut conversation),
            )
            .await
            .unwrap();
        assert_eq!(response.0, "收到");
        // The model request carried the full history + the new prompt.
        let reqs = fake.received_requests();
        assert_eq!(reqs.len(), 2, "model call + final answer round");
        let msgs = &reqs[0].messages;
        assert_eq!(msgs[0].content, "第一问", "{msgs:?}");
        assert_eq!(msgs[1].content, "第一答");
        assert_eq!(
            msgs[1].reasoning_content.as_deref(),
            Some("思考过程"),
            "reasoning must be replayed"
        );
        assert_eq!(msgs[2].content, "第二问");
        // The conversation came back complete (history + new turn + the
        // model's reply; mechanical injection blocks filtered out).
        assert_eq!(conversation.len(), 4, "{conversation:?}");
        assert_eq!(conversation[0].content, "第一问");
        assert_eq!(conversation[2].content, "第二问");
        assert_eq!(conversation[3].content, "收到");
        assert!(
            conversation
                .iter()
                .all(|m| !is_injected_block_text(&m.content)),
            "injection blocks filtered: {conversation:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// D3-1 (2026-08-14, ADR-0010 v1.10 / CONTEXT_COMPACTION_DESIGN §6): the
    /// restore write-back filter keeps the compaction marker and the
    /// whitelist block (a restored prompt must see the compression notice
    /// and the task facts) while still filtering other mechanical injected
    /// blocks.
    #[tokio::test]
    async fn conversation_writeback_retains_marker_and_whitelist() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };
        let fake = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::text("收到"),
            ScriptedResponse::text("收到"),
        ]));
        let controller = AgentLoopController::with_gateway(fake.clone());
        let mut conversation = vec![
            conv_message(Role::User, "第一问"),
            conv_message(
                Role::User,
                &crate::prompt::build_whitelist_block(&["任务背景：修复缓存回归".to_string()]),
            ),
            conv_message(
                Role::User,
                &crate::prompt::context_compressed_marker(3, 160_000, None),
            ),
            conv_message(Role::User, "[ORIENTATION v0.1] 当前任务是什么？"),
        ];
        let _ = controller
            .run_turn(
                &host,
                "第二问",
                "RUN-RETAIN",
                MANIFEST,
                0,
                None,
                None,
                Some(&mut conversation),
            )
            .await
            .unwrap();
        let kept: Vec<&str> = conversation.iter().map(|m| m.content.as_str()).collect();
        assert!(
            kept.iter()
                .any(|c| c.starts_with(crate::prompt::WHITELIST_PREFIX)),
            "whitelist must survive restore write-back: {kept:?}"
        );
        assert!(
            kept.iter()
                .any(|c| c.starts_with(crate::prompt::CONTEXT_COMPRESSED_PREFIX)),
            "marker must survive restore write-back: {kept:?}"
        );
        assert!(
            kept.iter().all(|c| !c.starts_with("[ORIENTATION")),
            "other injected blocks stay filtered: {kept:?}"
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// D2-2 (2026-08-14, ADR-0010 v1.10 / CONTEXT_COMPACTION_DESIGN §6): a
    /// restored conversation over the recovery window is mechanically
    /// truncated before the first request — whole old rounds dropped, the
    /// recovery marker inserted, the full sidecar copied into the run
    /// journal as the audit copy, and `context_recovery_truncated` journaled.
    #[tokio::test]
    async fn recovery_conversation_over_window_truncates_before_first_request() {
        let dir = test_dir();
        let journal = JournalRecorder::new(dir.clone());
        let host = TestHost {
            journal,
            tool_result: None,
        };
        let fake = Arc::new(FakeProvider::new(vec![
            ScriptedResponse::text("收到"),
            ScriptedResponse::text("收到"),
        ]));
        let controller =
            AgentLoopController::with_gateway(fake.clone()).with_recovery_compact(10, 2);
        let mut conversation = vec![conv_message(Role::User, "第一问")];
        conversation.extend(tool_round("call-r1", "第一轮工具结果"));
        conversation.extend(tool_round("call-r2", "第二轮工具结果"));
        let before = conversation.clone();
        let _ = controller
            .run_turn(
                &host,
                "第二问",
                "RUN-REC",
                MANIFEST,
                0,
                None,
                None,
                Some(&mut conversation),
            )
            .await
            .unwrap();
        let evs = events(&dir);
        let trunc: Vec<&RunEvent> = evs
            .iter()
            .filter(|e| e.event_type == EventType::ContextRecoveryTruncated)
            .collect();
        assert_eq!(trunc.len(), 1, "{evs:?}");
        assert!(
            trunc[0].payload["rounds_dropped"].as_u64().unwrap() >= 1,
            "must drop whole rounds: {:?}",
            trunc[0].payload
        );
        let audit = dir.join("recovery-conversation-full.json");
        assert!(audit.exists(), "full sidecar audit copy must exist");
        let audit_payload: serde_json::Value =
            serde_json::from_str(&std::fs::read_to_string(&audit).unwrap()).unwrap();
        assert_eq!(audit_payload, serde_json::to_value(&before).unwrap());
        // The recovery marker reaches the first model request and survives
        // the restore write-back (D3-1).
        let reqs = fake.received_requests();
        let first = &reqs[0].messages;
        assert!(
            first.iter().any(|m| m
                .content
                .starts_with(crate::prompt::CONTEXT_COMPRESSED_PREFIX)),
            "recovery marker must reach the first request: {first:?}"
        );
        assert!(
            conversation.iter().any(|m| m
                .content
                .starts_with(crate::prompt::CONTEXT_COMPRESSED_PREFIX)),
            "marker must survive write-back: {conversation:?}"
        );
        // No orphaned tool results after truncation: every Tool message's
        // call id must be declared by a surviving assistant message.
        let declared: Vec<&str> = conversation
            .iter()
            .filter(|m| m.role == Role::Assistant)
            .flat_map(|m| m.tool_calls.iter().map(|tc| tc.call_id.as_str()))
            .collect();
        for m in conversation.iter().filter(|m| m.role == Role::Tool) {
            assert!(
                m.tool_call_id
                    .as_deref()
                    .is_some_and(|id| declared.contains(&id)),
                "orphan tool result after truncation: {m:?}"
            );
        }
        let _ = std::fs::remove_dir_all(&dir);
    }

